"""Read the comments back from the warehouse and write the two files a model is shown.

`catalog/schema.md` is the full described schema. `catalog/index.md` has one line per
table. Both come from the warehouse, not from the YAML, so they show what is really there.
"""

import os
from pathlib import Path

from pyspark.sql import SparkSession

from pipeline.selection.catalog import DESCRIPTIONS_PATH, read_tables, render_index, render_schema
from pipeline.session import build_session

SCHEMA_FILE, INDEX_FILE = "schema.md", "index.md"
HEADER = (
    "<!-- Generated by `make catalog-export` from the comments in the warehouse. "
    "Edit catalog/tables.yaml, then run `make catalog-comments catalog-export`. -->\n\n"
)


def run(spark: SparkSession, out_dir: Path) -> tuple[Path, Path]:
    """Write both files. Returns their paths."""
    tables = list(read_tables(spark).values())
    out_dir.mkdir(parents=True, exist_ok=True)
    schema_path, index_path = out_dir / SCHEMA_FILE, out_dir / INDEX_FILE
    schema_path.write_text(HEADER + "# Warehouse schema\n\n" + render_schema(tables))
    index_path.write_text(HEADER + "# Warehouse tables\n\n" + render_index(tables))
    return schema_path, index_path


def main() -> None:
    out_dir = Path(os.environ.get("CATALOG_DIR", DESCRIPTIONS_PATH.parent))
    spark = build_session("catalog_export")
    for path in run(spark, out_dir):
        print(f"{path}: {len(path.read_text()):,} characters")
    spark.stop()


if __name__ == "__main__":
    main()
